/** One action. A field from another action is invalid_request. */
export type DatabasesRequest = DatabasesListRequest | DatabasesCreateRequest | DatabasesAcceptRequest | DatabasesAcceptLinkRequest | DatabasesSchemasRequest | DatabasesDeclareRequest | DatabasesGrantRequest | DatabasesRevokeRequest | DatabasesGrantsRequest | DatabasesHeadsRequest | DatabasesRelaysRequest | DatabasesBootstrapRelayRequest | DatabasesInviteRequest | DatabasesShareLinkRequest | DatabasesSubmitRequest | DatabasesStatusRequest;

/** The last publish attempt for one received database. It is kept in memory and is absent again after a restart. at is RFC 3339 UTC. status is the HTTP status when the service answered, or a string when the turn stopped before that answer: access_unknown, no_credentials, gap, spool_position_mismatch, empty_page, writer_tip, upload_identity, upload_position, reader_stopped, writer_stopped, confirm_failed, prepare_failed, queue_unreadable, spool_position, batch_invalid, entry_too_large, undo_failed, policy_unknown, local_store_unavailable, capture_disabled, payment_required, writer_sequence_unknown, or upload_unconfirmed. access_unknown means the self-access view was unknown or stale. no_credentials means the node had no usable cloud credentials for the share. policy_unknown, local_store_unavailable, and capture_disabled mean the node stopped for a local reason before it asked the cloud. payment_required means the account is unpaid. writer_sequence_unknown means the node lost its saved upload position and the cloud no longer keeps the delivered entries that show this device's last writer sequence, so the node does not guess one. status is null when the attempt failed before a status and the node had usable credentials. */
export interface DatabasesPublishAttempt {
  at: string;
  outcome: 'confirmed' | 'refused' | 'unconfirmed';
  status: number | string | null;
}

/** How many of this member's accepted local writes are still on the spool, and the last append attempt. pending is null until this process has seen the spool. Owned databases omit this object. */
export interface DatabasesPublish {
  /** Spool head minus the prefix the service has confirmed. Null when this process has not seen the spool, including after a restart. Zero when the registration is not a signed log. */
  pending: null | number;
  /** Null until a publish attempt, and null again after a restart. */
  lastAttempt: null | DatabasesPublishAttempt;
}

/** One database from list. A received database includes publish. An owned database omits it. */
export interface DatabasesListItem {
  publish?: DatabasesPublish;
  [key: string]: unknown;
}

export interface DatabasesListReply {
  ok: boolean;
  user_hash: string;
  databases: DatabasesListItem[];
  [key: string]: unknown;
}

/** create and accept. database is the owner row. */
export interface DatabasesDatabaseReply {
  ok: boolean;
  user_hash: string;
  database: { [key: string]: unknown };
  [key: string]: unknown;
}

export interface DatabasesSchemasReply {
  ok: boolean;
  user_hash: string;
  schemas: { [key: string]: unknown }[];
  /** Integer. Minimum 0. */
  count: number;
  [key: string]: unknown;
}

/** The owner declare-schema envelope. */
export interface DatabasesDeclareReply {
  ok: boolean;
  user_hash: string;
  schema_name: string;
  definition_id: string;
  resolution: 'register' | 'reuse';
  [key: string]: unknown;
}

/** grant and revoke. role is revoked after a revoke. entryHash and writerSeq name the signed entry on this node's publisher stream. */
export interface DatabasesGrantReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  /** 64 lowercase hex characters. */
  entryHash: string;
  /** Integer. Minimum 1. */
  writerSeq: number;
  role: 'read' | 'submit' | 'write' | 'revoked';
  [key: string]: unknown;
}

export interface DatabasesGrantMember {
  /** 64 lowercase hex characters. */
  nodeKey: string;
  role: 'read' | 'submit' | 'write';
}

/** The folded grants. A revoked member is absent. any is present only for public read. entryHash and writerSeq name the latest signed grant. */
export interface DatabasesGrantsReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  members: DatabasesGrantMember[];
  any?: 'read';
  entryHash?: string;
  /** Integer. Minimum 1. */
  writerSeq?: number;
  [key: string]: unknown;
}

export interface DatabasesHead {
  deviceId: string;
  /** Integer. Minimum 1. */
  writerSeq: number;
  entryHash: string;
}

export interface DatabasesHeadsReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  heads: DatabasesHead[];
  [key: string]: unknown;
}

export interface DatabasesRelaysReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  urls: string[];
  [key: string]: unknown;
}

export interface DatabasesBootstrapRelayReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  url: string;
  [key: string]: unknown;
}

/** The owner invitation envelope. invitation is the base64 sealed invitation. */
export interface DatabasesInviteReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  invitation: string;
  [key: string]: unknown;
}

/** The owner open read link envelope. link is one opaque token, not a URL. */
export interface DatabasesShareLinkReply {
  ok: boolean;
  user_hash: string;
  databaseId: string;
  link: string;
  [key: string]: unknown;
}

export interface DatabasesSubmitReply {
  ok: true;
  status: 'submitted';
  mutation_id: string;
  /** Integer. Minimum 1. */
  submission_sequence: number;
  [key: string]: unknown;
}

export interface DatabasesStatusReply {
  ok: true;
  mutation_id: string;
  status: string;
  [key: string]: unknown;
}

/** Success JSON for an action other than submit. submit answers 202. */
export type DatabasesReply = DatabasesListReply | DatabasesDatabaseReply | DatabasesSchemasReply | DatabasesDeclareReply | DatabasesGrantReply | DatabasesGrantsReply | DatabasesHeadsReply | DatabasesRelaysReply | DatabasesBootstrapRelayReply | DatabasesInviteReply | DatabasesShareLinkReply | DatabasesStatusReply;

/** Maximum items 256. */
export type ManifestNameList = string[];

/** Every schema on the node. It names none of them. A listing may carry it at every app API version. */
export type AllSchemas = '*';

/** Schema names the app asks for, or * for every schema. */
export type ManifestSchemaSide = AllSchemas | ManifestNameList;

/** The access block a developer writes in the app manifest. Publish reads read, write, and extensions and ignores any other key. read and write are each a list of schema names or the string *. A schema name is 1 to 128 characters of ASCII letters, digits, underscore, dot, slash, or hyphen. An extension name is 1 to 40 characters of lowercase ASCII letters, digits, or underscore. A name that breaks those rules fails publish with one generic message. The schema entry itself is not defined here. */
export interface ManifestAccess {
  /** Schemas the app reads. * means every schema and names none. */
  read: ManifestSchemaSide;
  /** Schemas the app writes. * means every schema and names none. It does not grant read. */
  write: ManifestSchemaSide;
  /** Extension names the app calls. The list is not limited to changes and databases. Install refuses a name this build cannot grant. This build grants changes and databases. * is not a value here. */
  extensions: ManifestNameList;
  [key: string]: unknown;
}

/** Schema name to the definition id of the one version the app was built against. At most 256 entries. A name is 1 to 128 characters of ASCII letters, digits, underscore, dot, slash, or hyphen. A definition id is 64 lowercase hex characters. */
export interface DefinitionMap {
  [key: string]: string;
}

/** Schema name to definition id, or * for every schema. */
export type ListingSchemaSide = AllSchemas | DefinitionMap;

/** The access block on the signed listing. Publish replaces each schema name with that name and its definition id. The string * stays * and means every schema. * is allowed at every app API version. Unknown keys are rejected. */
export interface ListingAccess {
  /** Schemas the app reads, or * for every schema. */
  read: ListingSchemaSide;
  /** Schemas the app writes, or * for every schema. */
  write: ListingSchemaSide;
  /** Extension names. An extension name is 1 to 40 characters of lowercase ASCII letters, digits, or underscore. Unknown names fail install. This build grants changes and databases. Maximum items 256. */
  extensions: string[];
}
